require "rails_helper"

RSpec.describe Timekeeping::MetricsClient do
  # The task reads metrics "read with the service identity"; with no token it must not send an unauthenticated request.
  it "refuses to call the metrics endpoint without the service token" do
    saved = ENV.to_h.slice("TIMEKEEPING_BASE_URL", "TIMEKEEPING_SERVICE_TOKEN")
    ENV["TIMEKEEPING_BASE_URL"] = "http://timekeeping.test"
    ENV.delete("TIMEKEEPING_SERVICE_TOKEN")
    stub_request(:get, "http://timekeeping.test/internal/v1/metrics").to_return(status: 200, body: "{}")

    expect { described_class.configured.fetch }.to raise_error(Timekeeping::MetricsClient::Unavailable)
    expect(a_request(:get, "http://timekeeping.test/internal/v1/metrics")).not_to have_been_made
  ensure
    %w[TIMEKEEPING_BASE_URL TIMEKEEPING_SERVICE_TOKEN].each { |key| ENV[key] = saved[key] }
  end
end

RSpec.describe Timekeeping::MetricsClient do
  # A malformed body must not pass through as quiet data that hides the reference_unavailable alert.
  it "treats a metrics body with non-numeric counts as unavailable without echoing the token" do
    saved = ENV.to_h.slice("TIMEKEEPING_BASE_URL", "TIMEKEEPING_SERVICE_TOKEN")
    token = SecureRandom.hex(24)
    ENV["TIMEKEEPING_BASE_URL"] = "http://timekeeping.test"
    ENV["TIMEKEEPING_SERVICE_TOKEN"] = token
    body = {
      "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
      "overflow_bucket" => "inf",
      "total_field" => "writes + reference_unavailable",
      "companies" => [
        { "company_id" => 7,
          "windows" => [{ "window_start" => "2026-05-01T12:00:00Z", "writes" => "98", "reference_unavailable" => "2",
                          "stale_generation" => 0, "latency_ms_sum" => 10, "latency_ms_buckets" => { "25" => 100 } }] }
      ]
    }
    stub_request(:get, "http://timekeeping.test/internal/v1/metrics")
      .with(headers: { "Authorization" => "Bearer #{token}" })
      .to_return(status: 200, body: JSON.generate(body), headers: { "Content-Type" => "application/json" })

    expect { described_class.configured.fetch }.to raise_error(Timekeeping::MetricsClient::Unavailable) { |error|
      expect(error.message).not_to include(token)
    }
  ensure
    %w[TIMEKEEPING_BASE_URL TIMEKEEPING_SERVICE_TOKEN].each { |key| ENV[key] = saved[key] }
  end
end
